import { Game } from "../../game";
import { Direction } from "../../game";
import { Room } from "../../room/room";

import { Enemy } from "./enemy";

import { Utils } from "../../utility/utils";
import { BeamEffect } from "../../projectile/beamEffect";
import { Player } from "../../player/player";
import { ImageParticle } from "../../particle/imageParticle";
import { Lighting } from "../../lighting/lighting";
import { Entity } from "../entity";
import { Random } from "../../utility/random";
import { GameplaySettings } from "../../game/gameplaySettings";
import { astar } from "../../utility/astarclass";
import { SpikeTrap } from "../../tile/spiketrap";

export class OccultistEnemy extends Enemy {
  static examineText = "An occultist. Shields allies and drags out fights.";
  ticks: number;
  seenPlayer: boolean;
  shieldedEnemies: Enemy[];
  range: number;
  static tileX: number = 55;
  static tileY: number = 8;
  lastHealth: number;

  constructor(room: Room, game: Game, x: number, y: number) {
    super(room, game, x, y);
    this.ticks = 0;
    this.health = 6;
    this.lastHealth = this.health;
    this.maxHealth = 6;
    this.defaultMaxHealth = 6;
    this.tileX = 55;
    this.tileY = 8;
    this.seenPlayer = true;
    this.name = "occultist";
    this.range = 6;
    this.aggro = false;
    this.frame = 0;
    this.hasShadow = true;
    this.shieldedBefore = false;
    this.shieldedEnemies = [];
    this.shadeColor = "#000000";
    this.lightSource = Lighting.newLightSource(
      this.x + 0.5,
      this.y + 0.5,
      [20, 0, 40],
      3.5,
      20,
    );
    this.addLightSource(this.lightSource);
    this.room.updateLighting();
    this.hasBloom = true;
    this.bloomColor = "#2E0854";
    this.bloomAlpha = 1;
    this.softBloomAlpha = 0;
    this.dropChance = 1;
    this.getDrop(["occultist"], false);
    this.pushable = false;
    this.chainPushable = false;
    this.destroyableByOthers = false;
    this.enemyKillXpMultiplier = 2;
  }

  hit = (): number => {
    return 1;
  };

  bleed = () => {};

  uniqueKillBehavior = () => {
    this.unshieldEnemies();
    this.removeLightSource(this.lightSource);
    this.lightSource = null;
  };

  behavior = () => {
    this.lastX = this.x;
    this.lastY = this.y;

    const enemiesToShield = this.enemyShieldCandidates();

    if (!this.dead) {
      if (this.handleSkipTurns()) return;

      this.ticks++;

      //if (this.ticks % 2 === 0) {
      this.shieldEnemies(enemiesToShield);
      this.updateShieldedEnemies();
      if (this.shieldedEnemies.length > 0) {
        // Choose the farthest shielded enemy
        let targetEnemy = this.shieldedEnemies.reduce((farthest, current) => {
          const dF = Utils.distance(this.x, this.y, farthest.x, farthest.y);
          const dC = Utils.distance(this.x, this.y, current.x, current.y);
          return dC > dF ? current : farthest;
        });

        // Build disable positions (other entities and nearby active spike traps)
        let disablePositions = Array<astar.Position>();
        disablePositions.push(...this.getEntityDisablePositions());
        for (let xx = this.x - 1; xx <= this.x + 1; xx++) {
          for (let yy = this.y - 1; yy <= this.y + 1; yy++) {
            if (
              this.room.roomArray[xx][yy] instanceof SpikeTrap &&
              (this.room.roomArray[xx][yy] as SpikeTrap).on
            ) {
              disablePositions.push({ x: xx, y: yy } as astar.Position);
            }
          }
        }

        // Localized A* toward the target enemy
        const moves = this.searchPathLocalizedCached(
          { x: targetEnemy.x, y: targetEnemy.y },
          disablePositions,
        );

        if (moves.length > 0) {
          const oldX = this.x;
          const oldY = this.y;
          const moveX = moves[0].pos.x;
          const moveY = moves[0].pos.y;

          // Move one step toward target enemy
          this.tryMove(moveX, moveY);
          this.setDrawXY(oldX, oldY);

          if (this.x > oldX) this.direction = Direction.RIGHT;
          else if (this.x < oldX) this.direction = Direction.LEFT;
          else if (this.y > oldY) this.direction = Direction.DOWN;
          else if (this.y < oldY) this.direction = Direction.UP;
        }
      } else {
        this.runAway();
      }
      //}
    }

    if (this.shieldedEnemies.length > 0) {
      this.shadeColor = "#2E0854";
    } else {
      this.shadeColor = "#000000";
    }
    if (this.lightSource) {
      this.lightSource.updatePosition(this.x + 0.5, this.y + 0.5);
    }

    // Keep shield beams anchored even when this enemy is simulated off-screen
    // (e.g., after teleporting outside the local interaction range).
    this.syncShieldBeamsToPositions();
  };

  onHurt = (damage: number = 1) => {
    if (
      this.health < this.lastHealth &&
      this.health % 2 === 0 &&
      this.health > 0
    ) {
      this.teleport();
    }
    this.lastHealth = this.health;
  };

  updateShieldedEnemies = () => {
    const myZ = this.z ?? 0;
    this.shieldedEnemies = this.shieldedEnemies.filter((enemy) => {
      if (enemy.dead) return false;

      // If an ally leaves our effective range/layer, the shield should drop immediately.
      const sameZ = (enemy.z ?? 0) === myZ;
      const inRange =
        Utils.distance(this.x, this.y, enemy.x, enemy.y) <= this.range;
      const shieldStillActive = enemy.shielded && enemy.shield;

      if (!sameZ || !inRange || !shieldStillActive) {
        if (!enemy.cloned && enemy.shielded) {
          enemy.removeShield();
        }
        return false;
      }

      return true;
    });
  };

  shieldEnemies = (enemiesToShield: Enemy[]) => {
    if (enemiesToShield.length > 0) {
      enemiesToShield.forEach((enemy) => {
        const distance = Utils.distance(this.x, this.y, enemy.x, enemy.y);
        if (Random.rand() * 10 > distance) {
          this.applyShieldTo(enemy);
        }
      });
    }
  };

  enemyShieldCandidates = (): Enemy[] => {
    const myZ = this.z ?? 0;
    const uncappedCandidates = this.room.entities.filter(
      (entity): entity is Enemy => {
        if (!(entity instanceof Enemy)) return false;
        if (entity === this) return false;
        if (entity.dead) return false;
        if (entity.shielded || entity.shieldedBefore) return false;
        if ((entity.z ?? 0) !== myZ) return false;
        return Utils.distance(this.x, this.y, entity.x, entity.y) <= this.range;
      },
    );
    return uncappedCandidates.slice(0, GameplaySettings.MAX_OCCULTIST_SHIELDS);
  };

  unshieldEnemies = () => {
    if (this.shieldedEnemies.length > 0) {
      for (let enemy of this.shieldedEnemies) {
        if (!enemy.cloned) {
          enemy.removeShield();
        }
      }
      this.shieldedEnemies = [];
    }
  };

  applyShieldTo = (enemy: Enemy) => {
    //this.shadeColor = "#2E0854";
    this.shadeMultiplier = 1.5;
    enemy.applyShield();
    this.shieldedEnemies.push(enemy);
    if (enemy.shielded && enemy.shield) {
      let beam = new BeamEffect(enemy.x, enemy.y, this.x, this.y, enemy);
      beam.compositeOperation = "source-over";
      beam.color = "#2E0854";
      beam.turbulence = 0.4;
      beam.gravity = 0.1;
      beam.iterations = 1;
      beam.segments = 100;
      beam.angleChange = 0.001;
      beam.springDamping = 0.01;
      beam.drawableY = enemy.drawableY;
      beam.type = "shield";
      this.room.projectiles.push(beam);
    }
  };

  private syncShieldBeamsToPositions = () => {
    for (const projectile of this.room.projectiles) {
      if (!(projectile instanceof BeamEffect)) continue;
      if (projectile.type !== "shield") continue;
      const parent = projectile.parent;
      if (!(parent instanceof Enemy)) continue;
      if (!this.shieldedEnemies.includes(parent)) continue;
      // Use raw tile positions (not draw offsets) so this stays correct even when not being drawn.
      projectile.setTarget(this.x, this.y, parent.x, parent.y);
      projectile.drawableY = parent.drawableY;
    }
  };

  teleport = () => {
    const newTile = this.findConstrainedFarTile(this.shieldedEnemies);
    if (!newTile) return;
    this.drawX = newTile.x - this.x;
    this.drawY = newTile.y - this.y;
    this.x = newTile.x;
    this.y = newTile.y;
    this.lightSource?.updatePosition(this.x + 0.5, this.y + 0.5);
    this.room.updateLighting();
    this.syncShieldBeamsToPositions();
  };

  private findConstrainedFarTile = (linked: Enemy[]) => {
    const emptyTiles = this.room.getEmptyTiles();
    const player = this.getPlayer();
    if (!player || player === false || emptyTiles.length === 0) return null;

    const interactionRange =
      GameplaySettings.MAXIMUM_ENEMY_INTERACTION_DISTANCE;
    const withinPlayerRange = (t: { x: number; y: number }) => {
      const dx = t.x - player.x;
      const dy = t.y - player.y;
      return dx * dx + dy * dy <= interactionRange * interactionRange;
    };

    const maxLinkedDist = this.range;
    const withinAllLinked = (t: { x: number; y: number }, dist: number) =>
      linked.every((e) => Utils.distance(t.x, t.y, e.x, e.y) <= dist);

    // Prefer tiles that keep us in range of the player AND all linked enemies.
    let candidates = emptyTiles.filter(
      (t) =>
        withinPlayerRange(t) &&
        (linked.length === 0 || withinAllLinked(t, maxLinkedDist)),
    );

    // If that's too strict, relax the linked constraint a bit (but still keep player interaction).
    if (candidates.length === 0 && linked.length > 0) {
      candidates = emptyTiles.filter(
        (t) => withinPlayerRange(t) && withinAllLinked(t, maxLinkedDist * 2),
      );
    }

    // As a last resort, just keep within player interaction range.
    if (candidates.length === 0) {
      candidates = emptyTiles.filter((t) => withinPlayerRange(t));
    }

    if (candidates.length === 0) return null;

    const tilesWithDistances = candidates.map((tile) => {
      const distance = Utils.distance(tile.x, tile.y, player.x, player.y);
      return { tile, distance };
    });
    tilesWithDistances.sort((a, b) => b.distance - a.distance);
    const farTiles = tilesWithDistances.slice(
      0,
      Math.max(1, Math.floor(tilesWithDistances.length / 2)),
    );
    const randomIndex = Math.floor(Random.rand() * farTiles.length);
    return farTiles[randomIndex]?.tile ?? null;
  };

  updateBeam = (delta: number) => {
    for (let beam of this.room.projectiles) {
      if (beam instanceof BeamEffect) {
        if (
          !this.shieldedEnemies.includes(beam.parent as Enemy) ||
          beam.type !== "shield"
        )
          continue;
        beam.setTarget(
          this.x - this.drawX,
          this.y - this.drawY,
          beam.parent.x - beam.parent.drawX,
          beam.parent.y - beam.parent.drawY,
        );
        beam.drawableY = beam.parent.drawableY;

        switch (Math.floor(this.frame)) {
          case 0:
            beam.color = "#2e0854";
            break;
          case 1:
            beam.color = "#331988";
            break;
          case 2:
            beam.color = "#4729db";
            break;
          case 3:
            beam.color = "#331988";
            break;
        }
      }
    }
  };

  draw = (delta: number) => {
    if (this.dead) return;
    Game.ctx.save();
    Game.ctx.globalAlpha = this.alpha;

    this.drawableY = this.y;
    if (!this.dead) {
      this.updateDrawXY(delta);
      this.updateBeam(delta);

      this.frame += 0.1 * delta;
      if (this.frame >= 4) this.frame = 0;

      if (this.hasShadow) this.drawShadow(delta);
      this.drawMobWithCrush(
        this.tileX + Math.floor(this.frame),
        this.tileY,
        1,
        2,
        this.x - this.drawX,
        this.y - this.drawYOffset - this.drawY,
        1,
        2,
        this.softShadeColor,
        this.shadeAmount(),
        undefined,
        this.outlineColor(),
        this.outlineOpacity(),
      );
    }
    Game.ctx.restore();
  };
}
