import { Entity, EntityType } from "../entity";
import { Room } from "../../room/room";
import { Game } from "../../game";
import { Sound } from "../../sound/sound";
import { Random } from "../../utility/random";
import { Berries } from "../../item/usable/berries";

export class Bush extends Entity {
  static examineText = "A bush. Rustles when you hit it.";
  constructor(room: Room, game: Game, x: number, y: number) {
    super(room, game, x, y);
    this.room = room;
    this.health = 1;
    this.maxHealth = 1;
    this.tileX = 19;
    this.tileY = 2;
    this.hasShadow = true;
    this.chainPushable = false;
    this.name = "bush";
    this.imageParticleX = 0;
    this.imageParticleY = 28;
    this.opaque = true;
    this.hitSound = Sound.playBush;
  }

  onHurt = () => {
    if (Random.rand() < 1 / 7)
      this.drops.push(new Berries(this.room, this.x, this.y));
  };

  // Dropping berries does not alter damage or survival. Changed handlers stay unknown.
  private readonly standardBushOnHurt = this.onHurt;
  getAgentKillDamageThreshold = (): number | null =>
    this.standardKillDamageThreshold(this.standardBushOnHurt);

  get type() {
    return EntityType.PROP;
  }

  draw = (delta: number) => {
    if (this.dead) return;
    Game.ctx.save();
    Game.ctx.globalAlpha = this.alpha;
    if (!this.dead) {
      this.updateDrawXY(delta);
      if (this.hasShadow) this.drawShadow(delta);

      Game.drawObj(
        this.tileX,
        this.tileY,
        2,
        2,
        this.x - this.drawX - 0.5,
        this.y - this.drawYOffset - this.drawY,
        2,
        2,
        this.room.shadeColor,
        this.shadeAmount(),
      );
    }
    Game.ctx.restore();
  };

  drawTopLayer = (delta: number) => {
    this.drawableY = this.y;
  };
}
