import { Game } from "../../game";
import { Room } from "../../room/room";
import { Player } from "../../player/player";
import { Item } from "../../item/item";
import { astar } from "../../utility/astarclass";
import { SpikeTrap } from "../../tile/spiketrap";
import { Enemy } from "./enemy";
import { StunAnimation } from "../../projectile/stunAnimation";
import { Utils } from "../../utility/utils";
import { globalEventBus } from "../../event/eventBus";

export class PawnEnemy extends Enemy {
  frame: number;
  ticks: number;
  seenPlayer: boolean;
  aggro: boolean;
  targetPlayer: Player;
  drop: Item;
  static difficulty: number = 4;
  static tileX: number = 23 + 28;
  static tileY: number = 8;
  static examineText = "A pawn. Harmless head-on—deadly on the diagonals.";

  constructor(room: Room, game: Game, x: number, y: number, drop?: Item) {
    super(room, game, x, y);
    this.ticks = 0;
    this.frame = 0;
    this.health = 1;
    this.maxHealth = 1;
    this.defaultMaxHealth = 1;
    this.tileX = 23;
    this.tileY = 12;
    this.seenPlayer = false;
    this.aggro = false;
    this.name = "pawn";
    // Chess-piece warnings should show the full threat pattern (no directional culling).
    this.hitWarningCullFactor = 0.4;
    // Pawns show only diagonal attack telegraphs
    this.orthogonalAttack = false;
    this.diagonalAttack = true;
    this.jumpHeight = 0.5;
    if (drop) this.drop = drop;
    this.armored = true;
    this.getDrop(["weapon", "equipment", "consumable", "tool", "coin"]);
  }

  hit = (): number => {
    return this.damage;
  };

  // Pawns can't move diagonally, so their hurt-retreat must be orthogonal-only.
  retreatOrthogonal = (oldX: number, oldY: number) => {
    const dxRaw = this.x - this.targetPlayer.x;
    const dyRaw = this.y - this.targetPlayer.y;
    const sx = Math.sign(dxRaw);
    const sy = Math.sign(dyRaw);

    const candidates: Array<{ x: number; y: number }> = [];

    const preferX = Math.abs(dxRaw) >= Math.abs(dyRaw);
    if (preferX) {
      if (sx !== 0) candidates.push({ x: this.x + sx, y: this.y });
      if (sy !== 0) candidates.push({ x: this.x, y: this.y + sy });
    } else {
      if (sy !== 0) candidates.push({ x: this.x, y: this.y + sy });
      if (sx !== 0) candidates.push({ x: this.x + sx, y: this.y });
    }

    for (const { x, y } of candidates) {
      if (!this.room.isTileEmpty(x, y)) continue;
      this.tryMove(x, y);
      this.setDrawXY(oldX, oldY);
      return;
    }
  };

  lookForPlayer = (face: boolean = true) => {
    if (this.seenPlayer) return;

    const p = this.nearestPlayer();
    if (p === false) return;

    const [distance, player] = p;
    if (distance > this.alertRange) return;

    this.targetPlayer = player;
    if (face) this.facePlayer(player);
    this.seenPlayer = true;

    globalEventBus.emit("EnemySeenPlayer", {
      enemyType: this.constructor.name,
      enemyName: this.name,
    });

    if (player === this.game.players[this.game.localPlayerID]) {
      this.alertTicks = 1;
    }

    this.conditionalHitWarnings();
  };
  behavior = () => {
    this.lastX = this.x;
    this.lastY = this.y;
    if (!this.dead) {
      if (this.handleSkipTurns()) return;
      this.ticks++;
      if (!this.seenPlayer) {
        // Don't carry a hurt-retreat across "sleeping" ticks.
        // (Matches the queen/king pattern: retreat is an immediate reaction.)
        this.justHurt = false;
        let p = this.nearestPlayer();
        if (p !== false) {
          let [distance, player] = p;
          if (distance <= 4) {
            this.targetPlayer = player;
            this.facePlayer(player);
            this.seenPlayer = true;
            if (player === this.game.players[this.game.localPlayerID])
              this.alertTicks = 1;
            this.conditionalHitWarnings();
          }
        }
      } else if (this.seenPlayer) {
        if (this.room.playerTicked === this.targetPlayer) {
          this.alertTicks = Math.max(0, this.alertTicks - 1);
          let oldX = this.x;
          let oldY = this.y;

          let disablePositions = Array<astar.Position>();
          disablePositions.push(...this.getEntityDisablePositions());
          for (let xx = this.x - 1; xx <= this.x + 1; xx++) {
            for (let yy = this.y - 1; yy <= this.y + 1; yy++) {
              if (
                this.room.roomArray[xx][yy] instanceof SpikeTrap &&
                (this.room.roomArray[xx][yy] as SpikeTrap).on
              ) {
                // don't walk on active spiketraps
                disablePositions.push({ x: xx, y: yy } as astar.Position);
              }
            }
          }
          if (this.justHurt) {
            // Retreat immediately after being hurt (before any attack logic).
            // This is what makes the pawn "jump back" on hit.
            if (this.targetPlayer) {
              this.retreatOrthogonal(oldX, oldY);
            }
            // If we don't have a target player (e.g. non-player damage), just consume the flag.
            this.justHurt = false;
          } else if (!this.unconscious) {
            // Diagonal-only attack: if player is diagonally adjacent, attack without moving
            const dxToPlayer = this.targetPlayer.x - this.x;
            const dyToPlayer = this.targetPlayer.y - this.y;

            if (Math.abs(dxToPlayer) === 1 && Math.abs(dyToPlayer) === 1) {
              this.targetPlayer.hurt(this.hit(), this.name, {
                source: { x: this.x, y: this.y },
              });
              this.drawX = 0.5 * (this.x - this.targetPlayer.x);
              this.drawY = 0.5 * (this.y - this.targetPlayer.y);
              if (
                this.targetPlayer === this.game.players[this.game.localPlayerID]
              )
                this.game.shakeScreen(10 * this.drawX, 10 * this.drawY);

              this.conditionalHitWarnings();
              return;
            }

            // Build grid like rookEnemy and use A* with orthogonal-only movement
            const moves = this.searchPathLocalizedCached(
              this.targetPlayer,
              disablePositions,
              { useLastPlayerPos: true, allowOmni: true },
            );

            if (moves.length > 0) {
              const moveX = moves[0].pos.x;
              const moveY = moves[0].pos.y;

              // Pawns cannot attack forward: if the next step is the player's tile, skip it
              const stepIsPlayer =
                this.targetPlayer.x === moveX && this.targetPlayer.y === moveY;

              // Avoid stepping onto active spike traps even if A* allowed it
              const targetTile = this.room.roomArray[moveX]?.[moveY];
              const isActiveSpike =
                targetTile instanceof SpikeTrap && (targetTile as SpikeTrap).on;

              if (!stepIsPlayer && !isActiveSpike) {
                this.tryMove(moveX, moveY);
                this.setDrawXY(oldX, oldY);
              }
            }
          }

          if (this.targetPlayer) this.conditionalHitWarnings();
        }

        let targetPlayerOffline =
          Object.values(this.game.offlinePlayers).indexOf(this.targetPlayer) !==
          -1;
        if (!this.aggro || targetPlayerOffline) {
          let p = this.nearestPlayer();
          if (p !== false) {
            let [distance, player] = p;
            if (
              distance <= 4 &&
              (targetPlayerOffline ||
                distance < this.playerDistance(this.targetPlayer))
            ) {
              if (player !== this.targetPlayer) {
                this.targetPlayer = player;
                this.facePlayer(player);
                if (player === this.game.players[this.game.localPlayerID])
                  this.alertTicks = 1;
                this.conditionalHitWarnings();
              }
            }
          }
        }
      }
    }
  };

  conditionalHitWarnings = () => {
    const distance = Utils.distance(
      this.x,
      this.y,
      this.targetPlayer.x,
      this.targetPlayer.y,
    );
    if (distance >= 2 || !this.targetPlayer)
      this.makeHitWarnings(undefined, undefined, true, "orthogonal");
    if (distance < 3 && this.targetPlayer) this.makeHitWarnings();
  };

  draw = (delta: number) => {
    if (this.dead) return;
    Game.ctx.save();
    Game.ctx.globalAlpha = this.alpha;
    //let offsetTileY = this.health <= 1 || this.cloned === true ? 2 : 0;

    if (!this.dead) {
      this.updateDrawXY(delta);
      this.frame += 0.1 * delta;
      if (this.frame >= 4) this.frame = 0;

      if (this.hasShadow) this.drawShadow(delta);
      this.drawMobWithCrush(
        this.tileX + Math.floor(this.frame),
        this.tileY,
        1,
        2,
        this.x - this.drawX,
        this.y - this.drawYOffset - this.drawY - this.jumpY,
        1,
        2,
        this.softShadeColor,
        this.shadeAmount(),
        undefined,
        this.outlineColor(),
        this.outlineOpacity(),
      );
    }
    if (!this.cloned) {
      if (!this.seenPlayer) {
        this.drawSleepingZs(delta);
      }
      if (this.alertTicks > 0) {
        this.drawExclamation(delta);
      }
    }
    Game.ctx.restore();
  };
}
