import { Player } from "../player/player";
import { ChatMessage, Game } from "../game";
import { Room, RoomType } from "../room/room";
import { GameConstants } from "../game/gameConstants";
import { SkinType, Tile } from "./tile";
import { UpLadder } from "./upLadder";
import { EVENTS } from "../event/events";
import { EventEmitter } from "../event/eventEmitter";
import { globalEventBus } from "../event/eventBus";
import { Sound } from "../sound/sound";
import { EnvType } from "../constants/environmentTypes";
import { LightSource } from "../lighting/lightSource";
import { Lockable, LockType } from "./lockable";
import { Key } from "../item/key";
import { Passageway } from "./passageway";
import { SidePathManager, SidePathOptions } from "../level/sidePathManager";

export class DownLadder extends Passageway {
  linkedRoom: Room;
  isSidePath = false;
  depth: number;
  environment: EnvType;
  lockable: Lockable;
  opts?: SidePathOptions;
  entryUpLadderPos?: { x: number; y: number };
  private sidePathManager: SidePathManager;
  private _generationInFlight: Promise<void> | null = null;

  constructor(
    room: Room,
    game: Game,
    x: number,
    y: number,
    isSidePath: boolean = false,
    environment: EnvType = EnvType.DUNGEON,
    lockType: LockType = LockType.NONE,
    opts?: SidePathOptions,
    lockStateOverride?: { lockType: LockType; keyID?: number },
  ) {
    super(room, game, x, y);
    this.linkedRoom = null;
    this.depth = room.depth;
    this.isSidePath = isSidePath;
    this.environment = environment;
    this.opts = opts;
    this.sidePathManager = new SidePathManager(game);

    // Determine effective lock based on save override, generator intent, or explicit param.
    // opts.locked === false opts out of the isSidePath default (used by cave pockets).
    const effectiveLockType = lockStateOverride
      ? lockStateOverride.lockType
      : isSidePath && !GameConstants.DEVELOPER_MODE && opts?.locked !== false
        ? LockType.LOCKED
        : lockType;

    // Initialize lockable using effective state (include saved keyID if provided)
    this.lockable = new Lockable(game, {
      lockType: effectiveLockType,
      keyID: lockStateOverride?.keyID,
      isTopDoor: false,
    });

    this.addLightSource();
  }

  getName = () => {
    return this.isSidePath ? "rope down" : "staircase down";
  };

  getTraversalTraits = () => {
    const unlocked = !this.lockable.isLocked();
    const player = this.game.players[this.game.localPlayerID];
    const hasMatchingKey = !!player && this.lockable.keyID > 0 &&
      this.lockable.hasKeyWithID(this.lockable.keyID, player) !== null;
    return {
      kind: "ladder", direction: "down", unlocked,
      unlockableFromHere: unlocked || hasMatchingKey || GameConstants.DEVELOPER_MODE,
      sidePath: this.isSidePath,
    };
  };

  examineText = (): string => {
    const locked = this.lockable?.isLocked?.() === true;
    if (this.isSidePath) {
      return locked
        ? "A rope down. It's locked."
        : "A rope down. It leads to a side path.";
    }
    return locked ? "A staircase down. It's locked." : "A staircase down.";
  };

  generate = async (): Promise<void> => {
    if (this.linkedRoom) return;
    if (this._generationInFlight) return await this._generationInFlight;
    this._generationInFlight = (async () => {
      await this.sidePathManager.generateFor(this);
    })();
    try {
      await this._generationInFlight;
    } finally {
      this._generationInFlight = null;
    }
  };

  // Linking logic is handled by SidePathManager

  private computePathId = (): string => {
    const parentPid: string = (this.game as any).currentPathId || "main";
    const roomAnchor = `${this.room.depth}:${this.room.roomX},${this.room.roomY}`;
    const tileAnchor = `${this.x},${this.y}`;
    return `sp:${parentPid}:${roomAnchor}:${tileAnchor}`;
  };

  private getMainPathDialogText = (): string => {
    return "A staircase leads down to the next floor.";
  };

  private getSidepathDialogText = (): string => {
    switch (this.environment) {
      case EnvType.FOREST:
        return "A rope descends into the lush forest below.";
      case EnvType.DARK_FOREST:
        return "A rope descends into the dark forest below.";
      case EnvType.CAVE:
        return "A rope descends into the cave below.";
      case EnvType.CAVE_POCKET:
        return "A rope descends into a hidden hollow below.";
      case EnvType.CASTLE:
        return "A rope descends into the castle below.";
      case EnvType.DARK_CASTLE:
        return "A rope descends into the cursed castle below.";
      case EnvType.GLACIER:
        return "A rope descends into the frozen glacier below.";
      case EnvType.DESERT:
        return "A rope descends into the desert ruins below.";
      case EnvType.SEWER:
        return "A rope descends into the sewer below.";
      case EnvType.MAGMA_CAVE:
        return "A rope descends into the magma cave below.";
      default:
        return "A rope descends into the unknown below.";
    }
  };

  // Public so the replay action processor can invoke the same descent path
  // without re-clicking the screenMessage button.
  confirmDescent = (player: Player) => {
    const pathId = this.isSidePath ? this.computePathId() : undefined;
    player.screenMessage.close();
    this.doEnterLevel(pathId);
  };

  doEnterLevel = (visitedPathId?: string) => {
    this.game.beginPreLevelGenFade(async () => {
      globalEventBus.emit(EVENTS.LEVEL_GENERATION_STARTED, {});
      await this.generate();
      globalEventBus.emit(EVENTS.LEVEL_GENERATION_COMPLETED, {});

      // Switch active path to this ladder's sidepath before transitioning
      this.sidePathManager.switchToPathBeforeTransition(this);

      // We can now allow the normal ladder loading screen to render.
      this.game.endPreLevelGenBlackout();

      for (const i in this.game.players) {
        const pl = this.game.players[i];
        pl.anchorOxygenLineToTile(this.room, this.x, this.y, {
          kind: "downLadder",
          angle: Math.PI / 2,
        });
        pl.getOxygenLine()?.update(true);
        this.game.changeLevelThroughLadder(this.game.players[i], this);
      }

      // Mark as visited using the ID captured at collision time (before any path switching).
      if (visitedPathId) {
        this.game.visitedSidepaths.add(visitedPathId);
      }
    });
  };

  onCollide = (player: Player) => {
    let allPlayersHere = true;
    for (const i in this.game.players) {
      const pl = this.game.players[i];
      const plRoom = (pl as any).getRoom
        ? (pl as any).getRoom()
        : this.game.levels[pl.depth].rooms[pl.levelID];
      if (plRoom !== this.room || pl.x !== this.x || pl.y !== this.y) {
        allPlayersHere = false;
      }
    }
    if (allPlayersHere) {
      if (!this.lockable.isLocked()) {
        const dialogText = this.isSidePath
          ? this.getSidepathDialogText()
          : this.getMainPathDialogText();
        const travelText = this.isSidePath ? "Travel" : "Descend";
        const replay = (this.game as any).replayManager;
        player.screenMessage.show(
          dialogText,
          [
            {
              text: travelText,
              onClick: () => {
                try { replay?.recordAction?.({ type: "LadderConfirm" }); } catch {}
                this.confirmDescent(player);
              },
            },
            {
              text: "Cancel",
              onClick: () => {
                try { replay?.recordAction?.({ type: "LadderCancel" }); } catch {}
                player.screenMessage.close();
              },
            },
          ],
        );
        return;
      }
      this.doEnterLevel();
    } else {
      if (player === this.game.players[this.game.localPlayerID])
        this.game.pushMessage("all players must be present");
    }
  };

  draw = (delta: number) => {
    let xx = 4;
    if (this.isSidePath) {
      xx = 16;
      if (this.lockable.isLocked()) xx = 17;
    }
    //if (this.environment === EnvType.FOREST) xx = 16;

    Game.drawTile(
      1,
      this.skin,
      1,
      1,
      this.x,
      this.y,
      1,
      1,
      this.room.shadeColor,
      this.shadeAmount(),
    );
    Game.drawTile(
      xx,
      0, //this.skin,
      1,
      1,
      this.x,
      this.y,
      1,
      1,
      this.room.shadeColor,
      this.shadeAmount(),
    );
  };

  drawAboveShading = (delta: number) => {
    // Update lockable animation
    this.lockable.update(delta);

    // Draw lock icon
    this.lockable.drawIcon(this.x, this.y, delta);

    // Update frame using parent method
    this.updateFrame(delta);
  };

  drawAbovePlayer = (delta: number) => {};

  isLocked(): boolean {
    return this.lockable.isLocked();
  }
}
