const GEN_VERSION = "levelgen-v1";

const stableRoomSort = (a: Room, b: Room): number => {
  if (a.depth !== b.depth) return a.depth - b.depth;
  const ap = a.pathId || "main";
  const bp = b.pathId || "main";
  if (ap !== bp) return ap < bp ? -1 : 1;
  if (a.mapGroup !== b.mapGroup) return a.mapGroup - b.mapGroup;
  if (a.roomX !== b.roomX) return a.roomX - b.roomX;
  if (a.roomY !== b.roomY) return a.roomY - b.roomY;
  return a.globalId < b.globalId ? -1 : a.globalId > b.globalId ? 1 : 0;
};

/**
 * Collect all rooms we should persist across every generated main-path depth and any
 * sidepaths reachable from them. Previously this only collected the current depth's
 * rooms, which caused prior floors to be wiped on save/load.
 *
 * Sidepath generation parameters live on the *main-path room's* rope-down ladder tiles,
 * so we BFS from main-path rooms into any sidepath room sets they link to.
 */
export const collectRoomsForSaveAtCurrentDepth = (game: Game): Room[] => {
  const seedRooms: Room[] = [];
  // Seed from every generated main-path level so visited floors persist.
  if (Array.isArray(game.levels)) {
    for (const lvl of game.levels) {
      if (lvl?.rooms?.length) seedRooms.push(...lvl.rooms);
    }
  }
  // Also include game.rooms (current level's rooms, which may include in-progress sidepaths
  // merged into the active level during play).
  if (Array.isArray(game.rooms)) seedRooms.push(...game.rooms);

  const byGid = new Map<string, Room>();
  for (const r of seedRooms) {
    if (!r) continue;
    byGid.set(r.globalId, r);
  }

  // BFS: follow rope-down ladders to include generated sidepath room sets at every depth.
  const queue: Room[] = Array.from(byGid.values());
  const visited = new Set<string>(queue.map((r) => r.globalId));

  while (queue.length > 0) {
    const r = queue.shift();
    if (!r) continue;
    for (let x = r.roomX - 1; x < r.roomX + r.width + 1; x++) {
      for (let y = r.roomY - 1; y < r.roomY + r.height + 1; y++) {
        const t = r.roomArray[x]?.[y];
        if (!(t instanceof DownLadder)) continue;
        if (t.isSidePath !== true) continue;
        const linked = t.linkedRoom;
        const lvlRooms = linked?.level?.rooms;
        if (!linked || !lvlRooms) continue;
        for (const rr of lvlRooms) {
          if (!rr) continue;
          byGid.set(rr.globalId, rr);
          if (!visited.has(rr.globalId)) {
            visited.add(rr.globalId);
            queue.push(rr);
          }
        }
      }
    }
  }

  return Array.from(byGid.values()).sort(stableRoomSort);
};

export const createSaveV2 = (game: Game, nowMs: number = Date.now()): Result<SaveV2> => {
  // Ensure builtin codecs are registered before we attempt to encode tiles.
  registerBuiltinTileCodecsV2();
  registerBuiltinItemCodecsV2();
  registerBuiltinEnemyCodecsV2();

  if (!game.levelgen) {
    return err({ kind: "InvalidState", message: "Cannot save: game.levelgen is missing" });
  }
  if (!game.level) {
    return err({ kind: "InvalidState", message: "Cannot save: game.level is missing" });
  }
  if (!Array.isArray(game.rooms)) {
    return err({ kind: "InvalidState", message: "Cannot save: game.rooms is not initialized" });
  }

  const roomsToSave = collectRoomsForSaveAtCurrentDepth(game);
  if (roomsToSave.length === 0) {
    return err({ kind: "InvalidState", message: "Cannot save: no rooms collected" });
  }

  // IMPORTANT: worldSpec env drives main-path regeneration. If we're currently inside a sidepath,
  // `game.level.environment.type` may reflect the sidepath environment, not the main path floor.
  const mainLevelEnvType = game.levels?.[game.level.depth]?.environment?.type;
  const envType = mainLevelEnvType ?? game.level.environment.type;

  // Deepest main-path floor that was actually generated this run. May exceed game.level.depth
  // when the player visited lower floors and then came back up before saving.
  const maxGeneratedDepth = (game.levels as (typeof game.levels[number] | undefined)[])
    .reduce<number>((max, l, idx) => (l ? Math.max(max, idx) : max), game.level.depth);

  const mainPathPlan: MainPathGenPlanV2[] = game.levels
    .filter((l) => l && typeof l.depth === "number" && l.depth <= maxGeneratedDepth)
    .map((l): MainPathGenPlanV2 => {
      const env = l.environment?.type ? envTypeToEnvKind(l.environment.type) : undefined;
      if (
        l.genSource === "png" &&
        typeof l.pngUrl === "string" &&
        l.pngUrl.length > 0
      ) {
        return { depth: l.depth, kind: "png", pngUrl: l.pngUrl, env };
      }
      return { depth: l.depth, kind: "procedural", env };
    })
    .sort((a, b) => a.depth - b.depth);

  const worldSpec: WorldSpecV2 = {
    seed: game.levelgen.seed,
    rngState: Random.state,
    genVersion: GEN_VERSION,
    depth: game.level.depth,
    maxGeneratedDepth,
    env: envTypeToEnvKind(envType),
    mainPathPlan,
    sidepaths: collectSidepaths(roomsToSave),
  };

  const delta: WorldDeltaV2 = {
    players: mapPlayers(game, game.players, nowMs),
    offlinePlayers: mapPlayers(game, game.offlinePlayers, nowMs),
    rooms: mapRooms(game, roomsToSave, nowMs),
    stats: statsTracker.getStats(),
    encounteredEnemies: game.encounteredEnemies.slice(),
    visitedSidepaths: game.visitedSidepaths ? [...game.visitedSidepaths] : [],
  };

  const replay = game.replayManager?.serialize?.() ?? undefined;

  const out: SaveV2 = {
    saveVersion: 2,
    meta: { savedAtMs: nowMs, developerMode: GameConstants.DEVELOPER_MODE },
    worldSpec,
    delta,
    ...(replay ? { replay } : {}),
  };

  return ok(out);
};

const collectSidepaths = (rooms: Room[]): SidepathSpecV2[] => {
  // Group by (depth, pathId) so a save with sidepaths on multiple floors regenerates each
  // sidepath at its original main-path depth. pathId alone isn't enough — sidepath RNG is
  // seeded with (seed + depth ^ pathHash), so depth disambiguation is required.
  const buckets = new Map<string, { pathId: string; depth: number; count: number }>();
  for (const r of rooms) {
    const pid = r.pathId || "main";
    if (pid === "main") continue;
    const key = `${r.depth}�${pid}`;
    const existing = buckets.get(key);
    if (existing) existing.count++;
    else buckets.set(key, { pathId: pid, depth: r.depth, count: 1 });
  }
  const out: SidepathSpecV2[] = [];
  for (const { pathId, depth, count } of buckets.values()) {
    out.push({ pathId, rooms: count, depth });
  }
  // Stable ordering for deterministic saves
  out.sort(
    (a, b) =>
      (a.depth ?? 0) - (b.depth ?? 0) ||
      (a.pathId < b.pathId ? -1 : a.pathId > b.pathId ? 1 : 0),
  );
  return out;
};

const mapPlayers = (
  game: Game,
  players: Record<string, Player>,
  nowMs: number,
): Record<string, PlayerSaveV2> => {
  const out: Record<string, PlayerSaveV2> = {};
  for (const [id, p] of Object.entries(players)) {
    out[id] = playerToSave(game, id, p, nowMs);
  }
  return out;
};

const playerToSave = (game: Game, id: string, p: Player, nowMs: number): PlayerSaveV2 => {
  const room = p.getRoom();
  const inventory = inventoryToSave(game, p.inventory, nowMs);
  return {
    id,
    x: p.x,
    y: p.y,
    dead: p.dead,
    direction: directionToDirectionKind(p.direction),
    health: p.health,
    maxHealth: p.maxHealth,
    mana: p.mana,
    maxMana: p.maxMana,
    roomGid: room.globalId,
    inventory,
    sightRadius: p.sightRadius,
    turnCount: p.turnCount,
    light: {
      equipped: p.lightEquipped,
      colorRgb: [p.lightColor[0], p.lightColor[1], p.lightColor[2]],
      brightness: p.lightBrightness,
    },
    knownSpells: p.knownSpells.length > 0 ? [...p.knownSpells] : undefined,
    knownWeaponIds: p.knownWeaponIds.length > 0 ? [...p.knownWeaponIds] : undefined,
  };
};

const inventoryToSave = (game: Game, inv: Player["inventory"], nowMs: number): InventorySaveV2 => {
  const totalSlots = (inv.rows + inv.expansion) * inv.cols;
  const slots = new Array<InventorySaveV2["slots"][number]>(totalSlots).fill(null);
  for (let i = 0; i < inv.items.length && i < totalSlots; i++) {
    const it = inv.items[i];
    if (!it) continue;
    const s = tryEncodeItem(game, it, nowMs);
    if (s) slots[i] = s;
  }
  const weaponIdx =
    inv.weapon === null ? undefined : inv.items.findIndex((it) => it === inv.weapon);
  const equippedWeaponSlot =
    weaponIdx !== undefined && weaponIdx >= 0 ? weaponIdx : undefined;
  return {
    isOpen: inv.isOpen,
    cols: inv.cols,
    rows: inv.rows,
    selX: inv.selX,
    selY: inv.selY,
    coins: inv.coins,
    expansion: inv.expansion,
    slots,
    equippedWeaponSlot,
  };
};

const mapRooms = (game: Game, rooms: Room[], nowMs: number): RoomDeltaV2[] => {
  return rooms.map((r) => roomToDelta(game, r, nowMs));
};

/**
 * Minimal room delta for now:
 * - records room identity + basic flags
 * - leaves tiles/entities/items/projectiles/hitWarnings empty
 *
 * This keeps SaveV2 schema-valid while we incrementally implement registries
 * and stable IDs for dynamic objects.
 */
const roomToDelta = (game: Game, r: Room, nowMs: number): RoomDeltaV2 => {
  const tiles = collectPersistedTiles(game, r, nowMs);
  const items = collectPersistedItems(game, r, nowMs);
  const enemies = collectPersistedEnemies(game, r, nowMs);
  const projectiles = collectPersistedProjectiles(game, r, nowMs);
  const hitWarnings = collectHitWarnings(r);
  return {
    roomGid: r.globalId,
    roomId: r.id,
    roomX: r.roomX,
    roomY: r.roomY,
    pathId: r.pathId || "main",
    mapGroup: r.mapGroup,
    depth: r.depth,
    entered: r.entered,
    active: r.active,
    onScreen: r.onScreen,
    tiles,
    enemies,
    items,
    projectiles,
    hitWarnings,
  };
};

const collectHitWarnings = (room: Room): RoomDeltaV2["hitWarnings"] => {
  const out: RoomDeltaV2["hitWarnings"] = [];
  for (const hw of room.hitwarnings) {
    if (!hw || hw.skipSave) continue;
    const { eX, eY, isEnemy, dirOnly } = hw.getSaveFields();
    out.push({ x: hw.x, y: hw.y, dead: hw.dead, eX, eY, isEnemy, dirOnly });
  }
  return out;
};

const collectPersistedProjectiles = (game: Game, room: Room, nowMs: number): RoomDeltaV2["projectiles"] => {
  const out: RoomDeltaV2["projectiles"] = [];
  for (const p of room.projectiles) {
    if (!p) continue;
    if (p instanceof WizardFireball) {
      out.push({
        kind: "wizard_fireball",
        gid: p.globalId,
        roomGid: room.globalId,
        x: p.x,
        y: p.y,
        dead: p.dead,
        parentGid: p.parent.globalId,
        state: p.state,
        delay: typeof p.delay === "number" ? p.delay : undefined,
      });
    }
    if (p instanceof BigWizardFireball) {
      out.push({
        kind: "big_wizard_fireball",
        gid: p.globalId,
        roomGid: room.globalId,
        x: p.x,
        y: p.y,
        dead: p.dead,
        parentGid: p.parent.globalId,
        state: p.state,
        delay: typeof p.delay === "number" ? p.delay : undefined,
      });
    }
    if (p instanceof PlayerFireball) {
      // Find the parent player's id key from game.players / offlinePlayers.
      let parentGid: string | null = null;
      for (const [id, pl] of Object.entries(game.players)) {
        if (pl === p.parent) { parentGid = id; break; }
      }
      if (parentGid === null) {
        for (const [id, pl] of Object.entries(game.offlinePlayers)) {
          if (pl === p.parent) { parentGid = id; break; }
        }
      }
      if (parentGid !== null) {
        out.push({
          kind: "player_fireball",
          gid: p.globalId,
          roomGid: room.globalId,
          x: p.x,
          y: p.y,
          dead: p.dead,
          parentGid,
          frame: p.frame,
          offsetFrame: p.offsetFrame,
          delay: p.delay,
        });
      }
    }
    if (p instanceof EnemySpawnAnimation) {
      const enemySave = tryEncodeEnemy(game, p.enemy, nowMs);
      if (!enemySave) continue;
      out.push({
        kind: "enemy_spawn_animation",
        gid: p.globalId,
        roomGid: room.globalId,
        x: p.x,
        y: p.y,
        dead: p.dead,
        enemy: enemySave,
      });
    }
  }
  return out;
};

const tileToKind = (t: Tile): TileKind | null => {
  if (t instanceof Door) return "door";
  if (t instanceof InsideLevelDoor) return "inside_level_door";
  if (t instanceof Button) return "button";
  if (t instanceof DownLadder) return "down_ladder";
  if (t instanceof UpLadder) return "up_ladder";
  if (t instanceof SpikeTrap) return "spike_trap";
  return null;
};

const collectPersistedTiles = (game: Game, room: Room, nowMs: number): TileSaveV2[] => {
  const out: TileSaveV2[] = [];
  const ctx = { game, nowMs };

  for (let x = room.roomX - 1; x < room.roomX + room.width + 1; x++) {
    for (let y = room.roomY - 1; y < room.roomY + room.height + 1; y++) {
      const t = room.roomArray[x]?.[y];
      if (!t) continue;
      const kind = tileToKind(t);
      if (!kind) continue;
      const codec = tileRegistryV2.get(kind);
      if (!codec) {
        throw new Error(`Missing Tile codec for kind=${kind}`);
      }
      out.push(codec.save(t, ctx));
    }
  }

  return out;
};

const tryEncodeItem = (game: Game, item: Item, nowMs: number): ItemSaveV2 | null => {
  const strictKinds = GameplaySettings.SAVE_V2_STRICT_KINDS;
  const kind = getItemKindV2(item);
  if (!kind) {
    if (strictKinds) {
      const name = item?.constructor?.name ?? "UnknownItem";
      throw new Error(`Missing Item kind mapping for ${name}`);
    }
    return null;
  }
  const codec = itemRegistryV2.get(kind);
  if (!codec) {
    if (strictKinds) {
      throw new Error(`Missing Item codec for kind=${kind}`);
    }
    return null;
  }
  return codec.save(item, { game, nowMs });
};

const collectPersistedItems = (game: Game, room: Room, nowMs: number): ItemSaveV2[] => {
  const out: ItemSaveV2[] = [];
  for (const it of room.items) {
    if (!it) continue;
    const encoded = tryEncodeItem(game, it, nowMs);
    if (encoded) {
      // Ensure room reference is set for in-world items
      encoded.roomGid = room.globalId;
      out.push(encoded);
    }
  }
  return out;
};

const tryEncodeEnemy = (game: Game, e: Entity, nowMs: number): EnemySaveV2 | null => {
  const strictKinds = GameplaySettings.SAVE_V2_STRICT_KINDS;
  const kind = getEnemyKindV2(e);
  if (!kind) {
    if (strictKinds) {
      const name = e?.constructor?.name ?? "UnknownEntity";
      throw new Error(`Missing Enemy kind mapping for ${name}`);
    }
    return null;
  }
  const codec = enemyRegistryV2.get(kind);
  if (!codec) {
    if (strictKinds) {
      throw new Error(`Missing Enemy codec for kind=${kind}`);
    }
    return null;
  }
  return codec.save(e, { game, nowMs });
};

const collectPersistedEnemies = (game: Game, room: Room, nowMs: number): EnemySaveV2[] => {
  const out: EnemySaveV2[] = [];
  for (const e of room.entities) {
    if (!e || e.dead) continue;
    const encoded = tryEncodeEnemy(game, e, nowMs);
    if (encoded) out.push(encoded);
  }
  return out;
};


